    prenomsTexte.Split('\n')
    |> Array.map (fun l ->
        let c = l.Split(';')
        { region = c[0]; sexe = c[1]; decennie = int c[2]; prenom = c[3]; naissances = int c[4] })
    |> List.ofArray
